-- Migration 094: Metro areas / chapter system (G5.3)
CREATE TABLE IF NOT EXISTS metro_areas (
  id             uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  created_at     timestamptz DEFAULT now() NOT NULL,
  name           text NOT NULL,
  slug           text NOT NULL UNIQUE,
  state          text NOT NULL,
  zip_codes      text[] NOT NULL DEFAULT '{}',
  status         text NOT NULL DEFAULT 'forming',
  coordinator_id uuid REFERENCES family_members(id) ON DELETE SET NULL,
  member_count   int NOT NULL DEFAULT 0,
  is_active      boolean NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS idx_metro_areas_zip ON metro_areas USING GIN (zip_codes);
CREATE INDEX IF NOT EXISTS idx_metro_areas_status ON metro_areas (status);
ALTER TABLE members ADD COLUMN IF NOT EXISTS metro_area_id uuid REFERENCES metro_areas(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS idx_members_metro ON members (metro_area_id);
CREATE OR REPLACE FUNCTION assign_metro_area(member_zip text)
RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT id FROM metro_areas WHERE member_zip = ANY(zip_codes) LIMIT 1;
$$;
CREATE OR REPLACE FUNCTION trg_assign_metro_area()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.zip_code IS NOT NULL THEN
    NEW.metro_area_id := assign_metro_area(NEW.zip_code);
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS assign_metro_on_member ON members;
CREATE TRIGGER assign_metro_on_member
  BEFORE INSERT OR UPDATE OF zip_code ON members
  FOR EACH ROW EXECUTE FUNCTION trg_assign_metro_area();
